use vstd::prelude::*;

verus! {
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        requires
            a.len() < 0x1_0000_0000, // Ensure the length of the vector is within a reasonable bound to avoid overflow
        ensures
            result.len() == a.len() && // The output vector has the same length as the input vector
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[i] // For every valid index, the elements are equal
    {
        let mut result: Vec<T> = Vec::new(); // Initialize an empty vector for the result
        let mut idx: usize = 0; // Initialize an index for iteration

        // Preallocate the result vector with the same length as the input vector
        result.resize(a.len(), a[0]); // Resize to the same length, using the first element as a placeholder

        while idx < a.len() // Loop until we have copied all elements
            invariant
                idx <= a.len(), // Ensure the index does not exceed the length of the input vector
                result.len() == a.len(), // The result vector has the same length as the input vector
                forall|i: nat| 0 <= i < idx ==> result[i] == a[i], // All copied elements are equal
            decreases a.len() - idx, // Decrease measure for termination
        {
            result[idx] = a[idx]; // Copy the element from the input vector to the result vector
            idx = idx + 1; // Increment the index
        }

        result // Return the copied vector
    }
}

